#!/usr/bin/env node
// scripts/chrome-listing-bundle.mjs
//
// Assemble dist/chrome-listing/ — everything to paste or upload by hand into the
// Chrome Web Store Developer Dashboard. The CWS API cannot set listing metadata
// or screenshots (it only uploads and publishes packages), so this is a
// hand-off, not a sync. Zero npm dependencies; Node 22 built-ins only.
//
//   pnpm listing:chrome
//
// Per locale (uk, en): name.txt, summary.txt, description.txt, screenshots/NN-name.png.
// Shared: icon-128.png, promo-tile-440x280.png, listing.txt (category, language,
// URLs), README.md (the upload steps).
//
// Fails loudly on a summary over 132 characters (the CWS cap). Missing
// screenshots are reported, not fatal: the text files are still produced.
//
// Env: OUT_DIR (default dist/chrome-listing), SCREENSHOTS_PATH (default
// apps/extension/store-assets/screenshots/chrome).

import { copyFileSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import nodePath from 'node:path';
import { fileURLToPath } from 'node:url';
import { discoverDesktopScreenshots, loadCopy } from './lib/amo-listing.mjs';

const repoRoot = nodePath.resolve(nodePath.dirname(fileURLToPath(import.meta.url)), '..');
const STORE_ASSETS = nodePath.join(repoRoot, 'apps/extension/store-assets');
const SUMMARY_MAX = 132; // CWS short description cap
const DESCRIPTION_MAX = 16_000; // REQUIREMENTS.md section 3
const LOCALE_LABEL = { uk: 'Ukrainian (uk)', en: 'English (en)' };

const env = (name, fallback = '') => (process.env[name] ?? '').trim() || fallback;

/** The listing markdown as plain text: the CWS description field does not render markdown. */
export function toPlainText(markdown) {
  return markdown
    .replace(/\r\n/g, '\n')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1 ($2)')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/(^|[\s(])_([^_\n]+)_(?=[\s).,;:!?]|$)/g, '$1$2')
    .replace(/(^|[\s(])\*([^*\n]+)\*(?=[\s).,;:!?]|$)/g, '$1$2')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/^[ \t]*[-*][ \t]+/gm, '• ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function fail(message) {
  console.error(`✗ ${message}`);
  process.exit(1);
}

function readme({ locales, listing, screenshotCounts, missingShots }) {
  const c = listing.chrome;
  const unverified = new Set(c.unverified);
  const flag = (k) =>
    unverified.has(k) ? ' (from the repo docs, not checked against the dashboard — confirm)' : '';
  const shotLine = (l) =>
    missingShots
      ? `- screenshots: **none yet** — the desktop screenshots folder is missing; run the bundle again once it exists.`
      : `- \`${l}/screenshots/\`: ${screenshotCounts[l]} file(s), 1280x800, upload in filename order.`;
  return `# Chrome Web Store listing — manual upload

Generated by \`pnpm listing:chrome\` from \`apps/extension/store-assets/\`. Do not edit
these files; change the sources (\`copy/*.md\`, \`listing.json\`, the screenshots) and rebuild.
The Chrome Web Store API cannot set listing text or screenshots, so this is done by hand
in the Developer Dashboard.

## Before you start

1. Open https://chrome.google.com/webstore/devconsole and pick **Movar**.
2. Upload the package first (or confirm the version) — the **Store listing** tab is separate
   from the package.
3. Open **Store listing** in the left menu.

## Default language: ${c.defaultLanguage}${flag('defaultLanguage')}

The dashboard has one main listing (the default language) and translations. Fill the
${c.defaultLanguage === 'en' ? 'English' : c.defaultLanguage} files into the main fields first, then add the other
language with the **Language** selector at the top of the Store listing tab
(**Add language** -> pick it -> fill the same fields from that folder).

## Per locale: ${locales.map((l) => LOCALE_LABEL[l] ?? l).join(', ')}

| Dashboard field | File |
| --- | --- |
| Name (from package; shown for reference) | \`<locale>/name.txt\` |
| **Summary** (short description, max ${SUMMARY_MAX} chars) | \`<locale>/summary.txt\` |
| **Description** | \`<locale>/description.txt\` — paste as plain text |
| **Screenshots** (1280x800, up to ${c.maxScreenshots}) | \`<locale>/screenshots/NN-*.png\` |

${locales.map((l) => shotLine(l)).join('\n')}

The name comes from the extension package (\`manifest.json\` / \`_locales\`), so changing it
means a new package, not a dashboard edit. \`name.txt\` is what the package should say.

## Shared assets (same for every language)

| Dashboard field | File |
| --- | --- |
| **Store icon** (128x128) | \`icon-128.png\` |
| **Small promo tile** (440x280) | \`promo-tile-440x280.png\` |

## Other Store listing fields

See \`listing.txt\`:

- **Category**: ${c.category}${flag('category')}
- **Official URL / Homepage URL**: ${c.homepageUrl}${flag('homepageUrl')}
- **Support URL / contact email**: ${c.supportEmail}${flag('supportEmail')}

## Privacy tab

Do not retype it. Copy each answer (single purpose, permission justifications, data usage
certifications) from \`apps/extension/store-assets/chrome/PRIVACY-FORM.md\`; the privacy
policy URL is ${c.privacyPolicyUrl}.

## Finish

1. Click **Save draft** on each tab; fix anything the dashboard flags.
2. **Submit for review** (or **Publish**) from the dashboard's **Status** area.
3. After it is live, open the public listing in each language and check the text, the
   screenshot order and the icon.
`;
}

function main() {
  const listing = JSON.parse(readFileSync(nodePath.join(STORE_ASSETS, 'listing.json'), 'utf8'));
  const c = listing.chrome;
  const locales = Object.keys(c.name);
  const copy = loadCopy(STORE_ASSETS, locales);

  // Validate everything before writing a byte.
  const problems = [];
  for (const l of locales) {
    const summary = copy[l].summary.cws;
    const n = [...summary].length;
    if (n > SUMMARY_MAX)
      problems.push(`${l} summary is ${n} chars, CWS caps it at ${SUMMARY_MAX}: "${summary}"`);
    const dn = [...toPlainText(copy[l].description)].length;
    if (dn > DESCRIPTION_MAX)
      problems.push(`${l} description is ${dn} chars, CWS caps it at ${DESCRIPTION_MAX}`);
  }
  for (const f of ['chrome/icon-128.png', 'chrome/promo-tile-440x280.png']) {
    if (!existsSync(nodePath.join(STORE_ASSETS, f))) problems.push(`missing ${f}`);
  }
  const shotRoot = nodePath.resolve(
    repoRoot,
    env('SCREENSHOTS_PATH', 'apps/extension/store-assets/screenshots/chrome'),
  );
  const shots = {};
  for (const l of locales) {
    const found = discoverDesktopScreenshots(shotRoot, l, { max: Infinity });
    problems.push(...found.problems);
    shots[l] = found;
  }
  if (problems.length > 0) {
    console.error(problems.map((p) => `✗ ${p}`).join('\n'));
    fail(`${problems.length} problem(s); nothing was written.`);
  }

  const out = nodePath.resolve(repoRoot, env('OUT_DIR', 'dist/chrome-listing'));
  rmSync(out, { recursive: true, force: true });
  mkdirSync(out, { recursive: true });

  const counts = {};
  for (const l of locales) {
    const dir = nodePath.join(out, l);
    mkdirSync(dir, { recursive: true });
    writeFileSync(nodePath.join(dir, 'name.txt'), `${c.name[l]}\n`);
    writeFileSync(nodePath.join(dir, 'summary.txt'), `${copy[l].summary.cws}\n`);
    writeFileSync(nodePath.join(dir, 'description.txt'), `${toPlainText(copy[l].description)}\n`);

    const found = shots[l];
    counts[l] = 0;
    if (found.missing) {
      console.warn(
        `! no screenshots for ${l} at ${nodePath.relative(repoRoot, shotRoot)}/${l}/ — text files only`,
      );
      continue;
    }
    const take = found.shots.slice(0, c.maxScreenshots);
    if (found.shots.length > take.length) {
      console.warn(
        `! ${l}: ${found.shots.length} screenshots, CWS takes ${c.maxScreenshots}; bundled the first ${take.length}, left out ${found.shots
          .slice(c.maxScreenshots)
          .map((s) => s.fileName)
          .join(', ')}`,
      );
    }
    mkdirSync(nodePath.join(dir, 'screenshots'), { recursive: true });
    for (const s of take) copyFileSync(s.path, nodePath.join(dir, 'screenshots', s.fileName));
    counts[l] = take.length;
  }

  copyFileSync(
    nodePath.join(STORE_ASSETS, 'chrome/icon-128.png'),
    nodePath.join(out, 'icon-128.png'),
  );
  copyFileSync(
    nodePath.join(STORE_ASSETS, 'chrome/promo-tile-440x280.png'),
    nodePath.join(out, 'promo-tile-440x280.png'),
  );
  writeFileSync(
    nodePath.join(out, 'listing.txt'),
    [
      `Category: ${c.category}`,
      `Default language: ${c.defaultLanguage}`,
      `Homepage URL: ${c.homepageUrl}`,
      `Support email: ${c.supportEmail}`,
      `Privacy policy URL: ${c.privacyPolicyUrl}`,
      '',
    ].join('\n'),
  );
  const missingShots = locales.every((l) => shots[l].missing);
  writeFileSync(
    nodePath.join(out, 'README.md'),
    readme({ locales, listing, screenshotCounts: counts, missingShots }),
  );

  console.log(
    `✓ ${nodePath.relative(repoRoot, out)}/ — ${locales.join(', ')}; screenshots: ${locales.map((l) => `${l}=${counts[l]}`).join(' ')}`,
  );
}

// Importable for tests without running; runs when invoked as a script.
if (process.argv[1] && nodePath.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
